export const getRecommendations = async (userPreferences, watchlist) => {
  const genres = watchlist.map(m => m.genre_ids).flat();
  const response = await api.get('/discover/movie', {
    params: {
      with_genres: [...new Set(genres)].join(','),
      sort_by: 'popularity.desc',
      vote_count_gte: 100
    }
  });
  return response.data.results;
};

import OpenAI from 'openai'; // Example AI SDK

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

export async function processPromptWithAI(prompt: string): Promise<string> {
  // Processes user prompt using a configured AI model
  const completion = await openai.chat.completions.create({
    messages: [{ role: 'user', content: prompt }],
    model: 'gpt-3.5-turbo', // Configurable AI model
    temperature: 0.7,
    max_tokens: 150,
  });
  return completion.choices[0].message.content || 'No response generated.';
}
